\title{Local and Analytic Structures Underlying the\\ Birch and Swinnerton-Dyer Conjecture}
\author{Aristotle}
\date{June 26, 2026}

\begin{document}
\begin{abstract}
The Birch and Swinnerton-Dyer (BSD) conjecture predicts that the algebraic rank of an elliptic curve $E/\QQ$ equals the analytic rank, the order of vanishing of its Hasse--Weil $L$-function $L(E,s)$ at $s=1$. We develop and rigorously verify the local and analytic structures underpinning this conjecture in five self-contained modules. On the local side: the equivalence between the Riemann Hypothesis over finite fields (Frobenius eigenvalues on $|z|=\sqrt p$) and the Hasse bound $a_p^2\le 4p$; the Vieta relations; the local functional equation $L_p(T)=pT^2L_p(1/(pT))$; Newton's recurrence $s_{n+2}=a_p s_{n+1}-p\,s_n$ for the power sums $s_n=\alpha^n+\beta^n$ with $s_0=2,\ s_1=a_p$; the point-count tower $\#E(\FF_{p^n})=p^n+1-s_n$; the Sato--Tate angle $a_p=2\sqrt p\cos\theta$; and the bound $\lVert\alpha^n+\beta^n\rVert\le 2(\sqrt p)^n$. On the analytic side: the analytic rank via order of vanishing, rank detection, leading-term factorization, additivity under products, and the unconditional parity theorem $(-1)^{\ord_{s=1}\Lambda}=w$ for $\Lambda(2-s)=w\,\Lambda(s)$. Finally a rank bridge: under the BSD rank equality, $L(E,1)=0$ iff $E(\QQ)$ is infinite. All results are machine-verified.
\end{abstract}
\maketitle

\section{Introduction}
Let $E/\QQ$ be an elliptic curve. Its \emph{algebraic rank} $r_{\mathrm{alg}}$ is the free rank of $E(\QQ)\cong\ZZ^{r_{\mathrm{alg}}}\times T$ ($T$ finite torsion); its \emph{analytic rank} is $r_{\mathrm{an}}=\ord_{s=1}L(E,s)$. The BSD conjecture asserts $r_{\mathrm{alg}}=r_{\mathrm{an}}$, and in refined form predicts the leading Taylor coefficient of $L(E,s)$ at $s=1$ via the regulator, the order of $\Sha$, the real period, and the Tamagawa numbers. We isolate and verify the scaffolding on which both sides rest, assembling it into a clean qualitative consequence of the rank equality. We do not claim a proof of BSD.

\section{The local $L$-factor and RH over finite fields}

\begin{definition}[Local $L$-factor]
At a good prime $p$, $L_p(T)=1-a_pT+pT^2$, with $a_p=p+1-\#E(\FF_p)$. Globally $L(E,s)=\prod_p L_p(p^{-s})^{-1}$.
\end{definition}

\begin{definition}[Frobenius polynomial]
The reciprocal roots of $L_p$ are the roots $\alpha,\beta$ of $f(X)=X^2-a_pX+p$.
\end{definition}

\begin{theorem}[RH over $\FF_p$ $\Leftrightarrow$ Hasse bound]
Let $a,p\in\RR$, $0<p$, and $z\in\CC$ with $f(z)=0$. Then $|z|^2=p \iff a^2\le 4p$.
\end{theorem}
\begin{proof}[Proof sketch]
Write $f(z)=0$ in real/imaginary parts. Forward: if $z\notin\RR$ then $z,\bar z$ are conjugate roots and $|z|^2=z\bar z=\alpha\beta=p$ with negative discriminant ($a^2\le4p$); if $z\in\RR$ then $|z|^2=z^2=p$ only at the double root, forcing $a^2=4p$. Converse: $a^2\le4p$ yields conjugate roots (Vieta) or a real double root, and a nonnegativity argument gives $|z|^2=p$.
\end{proof}

\begin{lemma}[Vieta]
Distinct roots $z\neq w$ satisfy $z+w=a$ and $zw=p$.
\end{lemma}
\begin{proof}[Proof sketch]
Subtracting $f(z)=f(w)=0$ gives $(z-w)(z+w-a)=0$; cancel $z-w\ne0$ for the sum, substitute back for the product.
\end{proof}

\begin{theorem}[Hasse bound]
If $0\le p$ and $a^2\le4p$ then $|a|\le 2\sqrt p$.
\end{theorem}
\begin{proof}[Proof sketch]
$(2\sqrt p)^2=4p\ge a^2$; take square roots using $a^2\le b^2,\ b\ge0\Rightarrow|a|\le b$.
\end{proof}

\begin{theorem}[Local functional equation]
For $T\ne0,\ p\ne0$, $\ L_p(T)=p\,T^2\,L_p\!\big(\tfrac{1}{pT}\big)$.
\end{theorem}
\begin{proof}[Proof sketch]
Substitute and clear denominators; a rational-function identity. It is the local incarnation of $s\leftrightarrow 2-s$.
\end{proof}

\begin{definition}[Point count]
$N_n:=\#E(\FF_{p^n})=p^n+1-(\alpha^n+\beta^n)$, with $N_0=0$, $N_1=p+1-a_p$, and $\lVert N_1-(p+1)\rVert\le2\sqrt p$.
\end{definition}

\section{The Frobenius trace recurrence and the Sato--Tate angle}
Let $s_n:=\alpha^n+\beta^n$.

\begin{theorem}[Newton's recurrence]
If $\alpha+\beta=a$ and $\alpha\beta=p$ then for all $n$,
\[ \alpha^{n+2}+\beta^{n+2}=a(\alpha^{n+1}+\beta^{n+1})-p(\alpha^n+\beta^n). \]
\end{theorem}
\begin{proof}[Proof sketch]
Substitute $a=\alpha+\beta$, $p=\alpha\beta$; both sides are equal polynomials in $\alpha,\beta$.
\end{proof}

\begin{definition}[Trace sequence]
$\operatorname{traceSeq}_{a,p}:\NN\to\CC$ with $s_0=2$, $s_1=a$, $s_{n+2}=a\,s_{n+1}-p\,s_n$. The value $s_0=2$ (not $1$) is forced by $\alpha^0+\beta^0=2$.
\end{definition}

\begin{theorem}[Trace sequence computes power sums]
If $\alpha+\beta=a$, $\alpha\beta=p$, then $\operatorname{traceSeq}_{a,p}(n)=\alpha^n+\beta^n$ for all $n$.
\end{theorem}
\begin{proof}[Proof sketch]
Two-step induction; bases $s_0=2$, $s_1=a$; step uses the recurrence and Newton's identity on the two predecessors.
\end{proof}

\begin{remark}
Thus the entire tower $\{N_n=p^n+1-\operatorname{traceSeq}_{a,p}(n)\}$ is determined by $(a_p,p)$ alone via a second-order linear recurrence; the local zeta function is $\frac{1-a_pT+pT^2}{(1-T)(1-pT)}$.
\end{remark}

\begin{theorem}[Sato--Tate angle]
If $0<p$ and $a^2\le4p$, there is $\theta\in[0,\pi]$ with $a=2\sqrt p\cos\theta$.
\end{theorem}
\begin{proof}[Proof sketch]
Take $\theta=\arccos(a/2\sqrt p)$; the Hasse bound places the argument in $[-1,1]$, so $\theta\in[0,\pi]$ and $\cos\theta=a/2\sqrt p$.
\end{proof}

\begin{theorem}[Archimedean / RH bound]
If $\lVert\alpha\rVert=\lVert\beta\rVert=\sqrt p$ then $\lVert\alpha^n+\beta^n\rVert\le 2(\sqrt p)^n$ for all $n$.
\end{theorem}
\begin{proof}[Proof sketch]
Triangle inequality and $\lVert\cdot\rVert$ multiplicative on powers: $\le\lVert\alpha\rVert^n+\lVert\beta\rVert^n=2(\sqrt p)^n$. Uses only the RH input.
\end{proof}

\section{Analytic rank and orders of vanishing}

\begin{definition}[Analytic rank]
For $L$ analytic at $s_0$, $\arank(L,s_0):=\ord_{s_0}L\in\NN$. For BSD, $s_0=1$.
\end{definition}

\begin{theorem}[Rank detection]
If $L$ is analytic at $s_0$ of finite order, then $\arank(L,s_0)=0\iff L(s_0)\ne0$, and $0<\arank(L,s_0)\iff L(s_0)=0$.
\end{theorem}
\begin{proof}[Proof sketch]
Order $0$ iff $L(s_0)\ne0$, finiteness ruling out the degenerate $\infty$ case; the positive form is the contrapositive.
\end{proof}

\begin{theorem}[Leading-term factorization]
If $r=\arank(L,s_0)$ is finite, there is $g$ analytic at $s_0$, $g(s_0)\ne0$, with $L(z)=(z-s_0)^r g(z)$ near $s_0$.
\end{theorem}
\begin{proof}[Proof sketch]
This is the defining property of the order of vanishing; $g(s_0)$ is the leading Taylor coefficient predicted by refined BSD.
\end{proof}

\begin{theorem}[Additivity]
For $f,g$ analytic at $s_0$ of finite order, $\arank(fg,s_0)=\arank(f,s_0)+\arank(g,s_0)$.
\end{theorem}
\begin{proof}[Proof sketch]
Orders of vanishing add under multiplication; the analytic shadow of the Artin/Rankin--Selberg factorization.
\end{proof}

\begin{remark}[Non-vacuity]
The model $\operatorname{modelL}_{r,c}(s)=(s-1)^r c$ is entire and, for $c\ne0$, has analytic rank exactly $r$ at $s=1$, with central value vanishing iff $r\ge1$. Hence the invariant is surjective onto $\NN$.
\end{remark}

\section{Functional equation, sign, and parity}
The completed $L$-function $\Lambda(E,s)=N^{s/2}(2\pi)^{-s}\Gamma(s)L(E,s)$ satisfies $\Lambda(E,2-s)=w(E)\Lambda(E,s)$, $w(E)\in\{\pm1\}$.

\begin{theorem}[Parity theorem]
Let $\Lambda$ be analytic at $1$ of finite order with $\Lambda(2-s)=w\,\Lambda(s)$, $w\in\{\pm1\}$. Then $(-1)^{\ord_{s=1}\Lambda}=w$.
\end{theorem}
\begin{proof}[Proof sketch]
Write $\Lambda(z)=(z-1)^r g(z)$, $g(1)\ne0$, $r=\ord_{s=1}\Lambda$. Since $z\mapsto2-z$ sends $z-1\mapsto-(z-1)$,
\[ \Lambda(2-z)=(-1)^r(z-1)^r g(2-z). \]
Equate with $w(z-1)^r g(z)$, cancel $(z-1)^r$, let $z\to1$: $(-1)^r g(1)=w\,g(1)$, so $(-1)^r=w$. Equivalently, Taylor coefficients obey $(-1)^k c_k=w\,c_k$; on $c_r\ne0$ this is $(-1)^r=w$.
\end{proof}

\begin{corollary}[Sign dichotomy]
If $w=-1$ then $\ord_{s=1}\Lambda$ is odd, so $\Lambda(1)=0$; and $\ord_{s=1}\Lambda$ is even iff $w=+1$.
\end{corollary}

\begin{remark}
The model $\Lambda(s)=(s-1)^r c$ satisfies the equation with sign $(-1)^r$, realizing both parities. Via BSD this is the Parity Conjecture $(-1)^{r_{\mathrm{alg}}}=w(E)$.
\end{remark}

\section{The rank bridge}
Model $E(\QQ)\cong\ZZ^r\times T$ with $T$ finite nonempty (the point at infinity $O\in T$).

\begin{theorem}[Mordell--Weil infinitude]
For $r\in\NN$ and $T$ finite nonempty, $\ZZ^r\times T$ is infinite iff $r>0$.
\end{theorem}
\begin{proof}[Proof sketch]
$r=0$: finite. $r\ge1$: inject $\ZZ\hookrightarrow\ZZ^r\times T$ via a single coordinate.
\end{proof}

\begin{theorem}[Local positivity]
For $p>1$ with $a^2\le4p$, $\ 0<p+1-a=\#E(\FF_p)$.
\end{theorem}
\begin{proof}[Proof sketch]
$a\le|a|\le2\sqrt p$; $p>1\Rightarrow(\sqrt p-1)^2>0\Rightarrow 2\sqrt p<p+1$, so $a<p+1$.
\end{proof}

\begin{theorem}[Qualitative BSD bridge]
Let $L$ be analytic at $1$ of finite order, and assume $\arank(L,1)=r$, the free rank of $E(\QQ)\cong\ZZ^r\times T$. Then $L(1)=0\iff E(\QQ)$ is infinite.
\end{theorem}
\begin{proof}[Proof sketch]
$L(1)=0\iff\arank(L,1)>0\iff r>0\iff E(\QQ)$ infinite, by rank detection, the rank equality, and the infinitude criterion.
\end{proof}

\begin{corollary}
Under the same hypotheses, $L(1)\ne0\iff E(\QQ)$ is finite.
\end{corollary}

\section{Applications and future work}
\textbf{Applications.} (i) Computing the full point-count tower from $(a_p,p)$; (ii) detecting positive rank from the root number ($w=-1\Rightarrow$ infinitely many points, under BSD); (iii) the Sato--Tate angle coordinate and its uniform norm control; (iv) stability of $L$-data under products/isogeny via additivity.

\textbf{Future directions.}
\emph{Conjecture 1 (Full Taylor reflection):} every coefficient obeys $c_k=(-1)^k w\,c_k$, so the expansion is supported on one parity.
\emph{Conjecture 2 (Multiplicativity of root numbers):} $(\Lambda_1\Lambda_2)(2-s)=(w_1w_2)(\Lambda_1\Lambda_2)(s)$, combining with additivity of orders.
\emph{Conjecture 3 (Hasse interval attained):} $a\mapsto\arccos(a/2\sqrt p)$ injective, order-reversing; $\#\{a:a^2\le4p\}\sim4\sqrt p$; limit measure $\frac2\pi\sin^2\theta\,d\theta$.
\emph{Conjecture 4 (Positivity/integrality):} $\operatorname{traceSeq}_{a,p}(n)\in\ZZ$ and $N_n>0$ for genuine curves.

