import math
from collections import Counter

def sato_tate_histogram(primes: list[int], bins: int = 12) -> dict[int, int]:
    """For each prime p and each admissible integer trace a with a^2 <= 4p,
    bin the Sato-Tate angle theta = arccos(a / (2 sqrt p)) in [0, pi]."""
    counts: Counter[int] = Counter()
    for p in primes:
        amax = int(math.isqrt(4 * p))
        for a in range(-amax, amax + 1):
            if a * a <= 4 * p:
                theta = math.acos(a / (2 * math.sqrt(p)))
                assert abs(a - 2 * math.sqrt(p) * math.cos(theta)) < 1e-9
                counts[min(int(theta / math.pi * bins), bins - 1)] += 1
    return dict(sorted(counts.items()))

if __name__ == "__main__":
    primes = [p for p in range(2, 2000)
              if all(p % d for d in range(2, int(p**0.5) + 1))]
    print("Sato-Tate angle histogram (bin -> count):")
    for b, c in sato_tate_histogram(primes).items():
        print(f"  bin {b:2d}: {'#' * (c // 40)} ({c})")
